import { useNavigate } from "@remix-run/react";
import { Image, Table, TableProps, Tag, Tooltip } from "antd"
import { format } from "date-fns";
import _ from "lodash";
import { useMemo } from "react";
import { IoEye } from "react-icons/io5";
import { Blog, Lab, useGetAllBlogs, useGetAllCategoriesBlog, useGetAllCategoriesLab, useGetAllLabs } from "~/data"

export const handle = {
  hideFooter: true,
  hideHeader: true,
  hideNavbar: true,
  hideCopyright: true,
}

export default function AdminKit() {
  const blogs = useGetAllBlogs();
  const categoryBlog = useGetAllCategoriesBlog();

  const navigate = useNavigate();

  const mapCategoryBlog = useMemo(() => {
    return _.mapKeys(categoryBlog.data?.data, it => it.categoryId);
  }, [categoryBlog.data?.data]);


  const datasource = useMemo(() => {
    return _(blogs.data?.data)
      .orderBy(it => it.updatedAt, "desc")
      .value();
  }, [blogs.data?.data]);

  const columns: TableProps<Blog>['columns'] = [
    {
      title: 'ID',
      dataIndex: 'blogId',
      key: 'blogId',
    },
    {
      title: 'Name',
      dataIndex: 'title',
      key: 'title',
      ellipsis: {
        showTitle: false,
      },
      render: (labName: string) => (
        <Tooltip placement="topLeft" title={labName}>
          {labName}
        </Tooltip>
      )
    },
    {
      title: 'Content',
      dataIndex: 'content',
      key: 'content',
      ellipsis: {
        showTitle: false,
      },
      render: (labDescription: string) => (
        <Tooltip placement="topLeft" title={labDescription}>
          {labDescription}
        </Tooltip>
      )
    },
    {
      title: 'Image',
      dataIndex: 'image',
      key: 'image',
      render: (text: string) => <Image src={text} width={50}
        fallback="data:image/png;base64,"
      />,
    },
    {
      title: 'Created At',
      dataIndex: 'createdAt',
      key: 'createdAt',
      ellipsis: {
        showTitle: false,
      },
      render: (text: string) => (
        <Tooltip placement="topLeft" title={format(text, "HH:mm:ss dd/MM/yyyy")}>
          {format(text, "HH:mm:ss dd/MM/yyyy")}
        </Tooltip>
      ),
    },
    {
      title: 'Updated At',
      dataIndex: 'updatedAt',
      key: 'updatedAt',
      ellipsis: {
        showTitle: false,
      },
      render: (text: string) => (
        <Tooltip placement="topLeft" title={format(text, "HH:mm:ss dd/MM/yyyy")}>
          {format(text, "HH:mm:ss dd/MM/yyyy")}
        </Tooltip>
      ),
    },
    {
      title: 'Category Name',
      dataIndex: 'categoryId',
      key: 'categoryId',
      render: (id: number) => mapCategoryBlog[id]?.categoryName,
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      render: (status: string) => {
        return (
          <Tag color={status.toLowerCase() == "active" ? "green" : "red"}>
            {status}
          </Tag>
        )
      },
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (record: Blog) => (
        <IoEye
          style={{ cursor: 'pointer' }}
          onClick={() => navigate(`/admin/blog/${record.blogId}`)}
        />
      ),
    },
  ];
  return (
    <div>
      <Table loading={blogs.isLoading} columns={columns} dataSource={datasource}>
      </Table>
    </div>
  )
}